      {"@context":"https://schema.org","@type":"Organization","name":"Axentra Solutions Pvt. Ltd.","url":"$SiteUrl/","logo":"$SiteUrl/assets/images/axentra-solutions-logo.jpeg","email":"$GeneralEmail","telephone":"+91 97250 24355","description":"An alternative legal and business process services company that works as an extended specialist team for clients in India and international markets.","sameAs":["$LinkedInUrl"]}
    </script>
