# How We Work
$managedProcess = @('Understand','Set up','Transition','Deliver','Review and improve')
$teamFactors = @('Scope and complexity','Volumes','Required skills','Seniority','Quality-review requirements','Working hours','Time-zone overlap','Client systems','Reporting requirements','Duration','Planned holiday and leave coverage')
