$howMain = @"
<section class="page-hero editorial-hero"><div class="container narrow"><p class="eyebrow">How we work</p><h1>Understand the work before establishing delivery</h1><p class="lead">Axentra reviews the work, expected volumes, systems, working hours, required experience, deadlines and expected outputs before proposing the team and delivery plan.</p><p>Where useful for the engagement, design-thinking methods help the teams understand user needs, dependencies and process friction before changes are proposed. Client feedback continues after delivery begins, so instructions, training and workflows remain aligned with the requirement.</p><a class="button primary" href="$BasePath/contact.html">Discuss Your Requirement</a></div></section>
<section class="section process-section"><div class="container"><div class="section-heading split-heading"><div><p class="eyebrow">Company-wide process</p><h2>Five steps from discussion to ongoing review</h2></div><p>The same core process applies across projects, recurring workflows, dedicated teams and secondments.</p></div>$(Get-ProcessMarkup -Items $managedProcess -Label 'Axentra delivery process')</div></section>
<section class="section section-muted"><div class="container"><div class="delivery-stage-grid"><article><p class="section-index">01</p><h3>Understand</h3><p>Review the work, expected volumes, systems, working hours, required experience, deadlines and expected outputs.</p></article><article><p class="section-index">02</p><h3>Set up</h3><p>Agree the team structure, roles, instructions, access, security, review layers, reporting and escalation routes.</p></article><article><p class="section-index">03</p><h3>Transition</h3><p>Complete knowledge transfer, training, system access, sample work, calibration and initial quality review.</p></article><article><p class="section-index">04</p><h3>Deliver</h3><p>Perform and review the work, track open items, manage exceptions and report against the agreed service requirements.</p></article><article><p class="section-index">05</p><h3>Review and improve</h3><p>Review quality findings, client feedback, recurring issues and delivery trends. Share relevant recommendations for instructions, training, templates, workflows, QA or product logic.</p></article></div></div></section>
<section class="section team-section"><div class="container"><div class="section-heading split-heading"><div><p class="eyebrow">Engagement-specific teams</p><h2>Teams structured for the engagement</h2></div><div><p>Axentra does not apply one fixed team model to every client or project.</p><p>The delivery team is arranged according to the work and the client's requirements.</p></div></div><div class="team-grid"><div><h3>The delivery team is arranged according to</h3>$(Get-ListMarkup -Items $teamFactors -ClassName 'output-list')</div><div><h3>Engagement teams can include</h3>$(Get-ListMarkup -Items $teamRoles -ClassName 'output-list')</div></div></div></section>
$(Get-ContactBand -Heading 'Discuss the work, team and coverage you need' -Copy 'Share the work type, volumes, systems, working hours, duration and review responsibilities.')
"@

