$securityMain = @"
<section class="page-hero editorial-hero"><div class="container narrow"><p class="eyebrow">Security &amp; Trust</p><h1>How Axentra protects client information</h1><p class="lead">Information security is addressed through employment and vendor obligations, internal policies, workforce training, approved IT assets, system-access controls and requirements agreed for the engagement.</p><p>Quality and security responsibilities are considered together during delivery setup. Team members receive access only to the information and systems required for their assigned roles.</p></div></section>
<section class="section section-muted"><div class="container"><div class="section-heading split-heading"><div><p class="eyebrow">Employment and vendor obligations</p><h2>Responsibilities apply to the people and providers involved</h2></div><p>Personnel and relevant vendors receive confidentiality, security and data-handling responsibilities before they receive access needed for the work.</p></div><div class="scope-grid">$(Get-ScopePanel -Title 'Employment obligations' -Items $peopleControls -Open)$(Get-ScopePanel -Title 'Vendor obligations' -Items $vendorControls -Open)</div></div></section>
<section class="section"><div class="container detail-layout"><div class="section-intro"><p class="eyebrow">Policies and training</p><h2>Clear instructions for handling client information</h2><p>Personnel acknowledge relevant policies, complete workforce training and receive any engagement-specific instructions before delivery begins.</p></div><div>$(Get-ListMarkup -Items $policyAreas -ClassName 'output-list')</div></div></section>
<section class="section section-dark"><div class="container"><div class="section-heading split-heading"><div><p class="eyebrow">IT assets and access</p><h2>Access is limited to the work assigned</h2></div><p>Devices, user accounts, permitted software and remote-working arrangements are set for the engagement. Access is changed or removed when a role or assignment ends.</p></div><div class="guardrail-grid"><article><h3>Before access</h3><p>Confirm the device, user role, permitted systems and client restrictions.</p></article><article><h3>During delivery</h3><p>Use the assigned access and follow the engagement's download, storage, software and remote-working rules.</p></article><article><h3>When access changes</h3><p>Remove or update access, return assets and complete the required information-return or deletion steps.</p></article></div></div></section>
<section class="section"><div class="container detail-layout"><div class="section-intro"><p class="eyebrow">Information handled</p><h2>Safeguards reflect the information involved</h2><p>Axentra identifies the types of information involved and follows the client, legal and contract terms that apply to their handling.</p></div><div>$(Get-ListMarkup -Items $informationCategories -ClassName 'output-list')</div></div></section>
<section class="section section-muted"><div class="container"><div class="section-heading split-heading"><div><p class="eyebrow">AI use</p><h2>Use is limited by client instructions and engagement terms</h2></div><p class="statement">Client information is not entered into unauthorised public AI tools or used by Axentra for independent model training.</p></div>$(Get-ListMarkup -Items $responsibleAi -ClassName 'output-list')</div></section>
<section class="section"><div class="container security-response-grid"><article><p class="eyebrow">Incident response</p><h2>Report, contain and respond</h2><p>Personnel report suspected incidents through an internal escalation route. According to the engagement terms, response covers containment, access changes, record preservation, client notification, corrective action and recovery as applicable.</p></article><article><p class="eyebrow">Business continuity</p><h2>Plan for interruptions</h2><p>Staffing, access, communication and recovery arrangements are considered during setup. Continuity steps are aligned with the work and the client's priorities.</p></article></div></section>
<section class="section section-dark"><div class="container trust-grid"><article><p class="eyebrow">PHI and HIPAA-related engagements</p><h2>Confirm roles before processing</h2><p>Where work involves protected health information, the parties address permitted use, safeguards, access, incident duties and any Business Associate Agreement before processing begins. Axentra does not describe itself as HIPAA certified.</p></article><article><p class="eyebrow">Certification position</p><h2>Claims reflect the current position</h2><p>Axentra does not claim an information-security or privacy certification it has not obtained. Relevant policies, practices and available documentation can be discussed during client diligence.</p></article></div></section>
$(Get-ContactBand -Eyebrow 'Client diligence' -Heading 'Discuss security and data-handling requirements' -Copy 'Clients can review the information involved, access arrangements, contract terms and available documents before the engagement begins.')
"@

