$legalMain = @"
<section class="page-hero policy-hero"><div class="container narrow"><p class="eyebrow">Legal Notice</p><h1>Website and service boundaries</h1><p>Clear terms for use of this website and the role Axentra describes on it.</p></div></section>
<section class="section"><div class="container policy-content"><h2>Axentra's role</h2><p>Axentra Solutions Pvt. Ltd. is not a law firm and does not provide legal representation. Use of this website, submission of an enquiry or communication with Axentra does not create a lawyer-client relationship.</p><p>Website information is general and is not legal, financial, lending, servicing, tax or other professional advice.</p><h2>Mortgage and bankruptcy boundaries</h2><p>Axentra does not act as a lender, licensed mortgage servicer, foreclosure counsel or debt collector unless a role is separately authorised and all applicable requirements are confirmed. Delivery is performed within the scope, systems, instructions and review arrangements agreed with the client.</p><h2>Website use</h2><p>Use the website lawfully and do not attempt to interfere with its availability, security or content. Do not send client files or sensitive records through general website or email channels unless a secure transfer arrangement has been established.</p><h2>Intellectual property</h2><p>Website content, branding and original materials belong to Axentra or the relevant owner. They cannot be represented as another party's work or reused in a misleading manner.</p><h2>External links</h2><p>External links are provided for reference. A link does not imply endorsement, control or responsibility for the external service or its content.</p><h2>Contact</h2><p>Questions about this notice can be sent to <a href="mailto:$GeneralEmail">$GeneralEmail</a>.</p></div></section>
"@

Write-SiteFile -Path 'legal-notice.html' -Content (Get-Page -Title 'Legal Notice | Axentra' -Description 'Axentra legal notice covering website use, service boundaries, no lawyer-client relationship, intellectual property, external links and contact information.' -Canonical "$SiteUrl/legal-notice.html" -Active '' -Main $legalMain -BodyClass 'policy-page')

# Privacy Notice
$privacyMain = @"
<section class="page-hero policy-hero"><div class="container narrow"><p class="eyebrow">Privacy Notice</p><h1>Website enquiries and information handling</h1><p>This notice describes information handled through the public Axentra website and general contact routes.</p></div></section>
<section class="section"><div class="container policy-content"><h2>Information provided by you</h2><p>The contact form prepares an email in your own email application. The website does not transmit or store the fields. If you send the email, Axentra receives the name, organisation, work email, country or market, service, engagement type, approximate volume or team requirement, preferred working hours, expected duration and description you choose to include.</p><p>Axentra also receives information sent directly to its published email addresses or LinkedIn account.</p><h2>Purpose</h2><p>Enquiry information is used to respond, understand the stated requirement, arrange a discussion, maintain relevant correspondence and meet legal or security obligations.</p><h2>Technical information and analytics</h2><p>The website code does not use analytics, advertising trackers, account profiles or tracking cookies. It does not set optional cookies. GitHub Pages hosts the website and processes standard technical request information under its own terms.</p><h2>Storage, access and service providers</h2><p>Information sent by email is stored in the applicable email environment and accessed by personnel involved in responding to the enquiry, subject to organisational and provider controls. Hosting and communication providers process information only for the services they provide.</p><h2>Retention</h2><p>Enquiry records are retained only for a relevant business, security, contractual or legal purpose, then deleted or retained under the applicable record requirement.</p><h2>Your choices and rights</h2><p>You can ask Axentra to access, correct or delete enquiry information, or raise a privacy question. Applicable rights depend on the information and governing law.</p><h2>Contact</h2><p>Send privacy requests to <a href="mailto:$GeneralEmail">$GeneralEmail</a>. Do not include sensitive case, borrower, health, loan or client records in the first message.</p></div></section>
"@

Write-SiteFile -Path 'privacy-notice.html' -Content (Get-Page -Title 'Privacy Notice | Axentra' -Description 'Axentra website privacy notice covering contact-form and email enquiries, technical information, analytics, storage, access, retention, providers and user rights.' -Canonical "$SiteUrl/privacy-notice.html" -Active '' -Main $privacyMain -BodyClass 'policy-page')

# Accessibility
$accessibilityMain = @"
<section class="page-hero policy-hero"><div class="container narrow"><p class="eyebrow">Accessibility</p><h1>Access to Axentra's website</h1><p>The website is designed for keyboard use, readable contrast, responsive layouts and clear content structure.</p></div></section>
<section class="section"><div class="container policy-content"><h2>Accessibility measures</h2><p>Pages use semantic headings and landmarks, visible keyboard focus, a skip link, text alternatives for meaningful images, labelled form controls and process lists that remain readable without visual connectors.</p><h2>Responsive use</h2><p>Navigation, service scopes, process steps and contact fields adapt for desktop, tablet and mobile screens. Motion is limited and disabled where a user requests reduced motion.</p><h2>Feedback</h2><p>If any page, control or document is difficult to use, email <a href="mailto:$GeneralEmail">$GeneralEmail</a> with the page address and a short description of the problem.</p></div></section>
"@

Write-SiteFile -Path 'accessibility.html' -Content (Get-Page -Title 'Accessibility | Axentra' -Description 'Accessibility information for the Axentra website, including keyboard use, contrast, semantic structure, responsive layouts and feedback.' -Canonical "$SiteUrl/accessibility.html" -Active '' -Main $accessibilityMain -BodyClass 'policy-page')
